function levelOrder(root) {
    const res = [];
    if (!root) return res;
    const q = [root];
    while (q.length > 0) {
        const level = [];
        const len = q.length;
        for (let i = 0; i < len; i++) {
            const node = q.shift();
            level.push(node.val);
            if (node.left) q.push(node.left);
            if (node.right) q.push(node.right);
        }
        res.push(level);
    }
    return res;
}
